<?php
namespace App\Http\Controllers\Api;
use App\Http\Controllers\Controller;
use App\Models\MeasurementProfile;
use Illuminate\Http\Request;
use Illuminate\Validation\Rule;
class MeasurementProfileController extends Controller {
 public function index(Request $request){$q=MeasurementProfile::with('measurements')->where('client_id',$request->user()->id);if($request->user()->role==='stylist'){$q=MeasurementProfile::whereHas('client.clientOrders',fn($x)=>$x->where('stylist_id',$request->user()->id))->with('measurements');}return $q->latest()->get();}
 public function store(Request $request){$clientRule=$request->user()->role==='stylist'?['required','integer',Rule::exists('users','id')->where('role','client')]:['prohibited'];$data=$request->validate(['client_id'=>$clientRule,'label'=>'required|string|max:120','notes'=>'nullable|string','measurements'=>'nullable|array:chest,waist,hips,shoulder,sleeve,length','measurements.chest'=>'nullable|numeric|min:0|max:9999.99','measurements.waist'=>'nullable|numeric|min:0|max:9999.99','measurements.hips'=>'nullable|numeric|min:0|max:9999.99','measurements.shoulder'=>'nullable|numeric|min:0|max:9999.99','measurements.sleeve'=>'nullable|numeric|min:0|max:9999.99','measurements.length'=>'nullable|numeric|min:0|max:9999.99']);$clientId=$request->user()->role==='client'?$request->user()->id:$data['client_id'];$profile=MeasurementProfile::create(['client_id'=>$clientId,'label'=>$data['label'],'notes'=>$data['notes']??null]);if(!empty($data['measurements']))$profile->measurements()->create($data['measurements']);return response()->json($profile->load('measurements'),201);}
 public function show(Request $request, MeasurementProfile $measurement_profile){$this->authorizeProfile($request,$measurement_profile);return $measurement_profile->load('measurements');}
 public function update(Request $request, MeasurementProfile $measurement_profile){$this->authorizeProfile($request,$measurement_profile);$data=$request->validate(['label'=>'sometimes|string|max:120','notes'=>'nullable|string','measurements'=>'nullable|array:chest,waist,hips,shoulder,sleeve,length','measurements.chest'=>'nullable|numeric|min:0|max:9999.99','measurements.waist'=>'nullable|numeric|min:0|max:9999.99','measurements.hips'=>'nullable|numeric|min:0|max:9999.99','measurements.shoulder'=>'nullable|numeric|min:0|max:9999.99','measurements.sleeve'=>'nullable|numeric|min:0|max:9999.99','measurements.length'=>'nullable|numeric|min:0|max:9999.99']);$measurement_profile->update($data);if(!empty($data['measurements']))$measurement_profile->measurements()->create($data['measurements']);return $measurement_profile->load('measurements');}
 public function destroy(Request $request, MeasurementProfile $measurement_profile){$this->authorizeProfile($request,$measurement_profile);$measurement_profile->delete();return response()->noContent();}
 private function authorizeProfile(Request $request, MeasurementProfile $profile){if($request->user()->role==='client')abort_unless($profile->client_id===$request->user()->id,404);else abort_unless($request->user()->stylistOrders()->where('client_id',$profile->client_id)->exists(),404);}
}
